using System;
using System.IO;
using System.Windows.Media.Imaging;

namespace OpticalTransfer.UI.Theme
{
    public static class LogoAsset
    {
        private const string Base64Png = "";

        public static BitmapImage GetLogoImage()
        {
            try
            {
                byte[] binaryData = Convert.FromBase64String(Base64Png);
                BitmapImage bi = new BitmapImage();
                bi.BeginInit();
                bi.StreamSource = new MemoryStream(binaryData);
                bi.CacheOption = BitmapCacheOption.OnLoad;
                bi.EndInit();
                bi.Freeze();
                return bi;
            }
            catch
            {
                return null;
            }
        }
    }
}
